let reads = 0;
function index(): number { reads += 1; return 0; }
const numbers: number[] = [0];
const strings: string[] = [''];
const booleans: boolean[] = [false];
const objects: { readonly name: string }[] = [{ name: 'array' }];
console.log(`${numbers[index()]!} ${reads}`);
console.log(`'${strings[index()]!}' ${reads}`);
console.log(`${booleans[index()]!} ${reads}`);
console.log(`${objects[index()]!.name} ${reads}`);

let calls = 0;
function number(): number | undefined { calls += 1; return 0; }
function text(): string | undefined { calls += 1; return ''; }
function boolean(): boolean | undefined { calls += 1; return false; }
class Source {
    read(): string | undefined { calls += 1; return ''; }
}
const source = new Source();
const result = (): number | undefined => { calls += 1; return 0; };
console.log(`${number()!} ${calls}`);
console.log(`'${text()!}' ${calls}`);
console.log(`${boolean()!} ${calls}`);
console.log(`'${source.read()!}' ${calls}`);
console.log(`${result()!} ${calls}`);

let calls = 0;
function box(): { readonly n: number; readonly s: string; readonly b: boolean } | undefined {
    calls += 1;
    return { n: 0, s: '', b: false };
}
console.log(`${box()?.n!} ${calls}`);
console.log(`'${box()?.s!}' ${calls}`);
console.log(`${box()?.b!} ${calls}`);
class Item { value(): number { return 0; } }
function item(): Item | undefined { calls += 1; return new Item(); }
console.log(`${item()?.value()!} ${calls}`);

function run(box: { n?: number; s?: string; readonly object?: { readonly name: string } }): void {
    console.log(`${box.n!} '${box.s!}' ${box.object!.name}`);
    if (box.n !== undefined) { console.log(`${(box.n)!}`); }
    if (box.s !== undefined) { console.log(`'${box.s!}'`); }
}
run({ n: 0, s: '', object: { name: 'field' } });
let calls = 0;
function box(): { readonly value?: number } { calls += 1; return { value: 0 }; }
console.log(`${box().value!} ${calls}`);

let calls = 0;
function key(): string { calls += 1; return 'key'; }
const numbers = new Map<string, number>([['key', 0]]);
const strings = new Map<string, string>([['key', '']]);
const booleans = new Map<string, boolean>([['key', false]]);
const objects = new Map<string, { readonly name: string }>([['key', { name: 'map' }]]);
console.log(`${numbers.get(key())!} ${calls}`);
console.log(`'${strings.get(key())!}' ${calls}`);
console.log(`${booleans.get(key())!} ${calls}`);
console.log(`${objects.get(key())!.name} ${calls}`);

function run(n: number | undefined, b: boolean | undefined, s: string | undefined): void {
    if (n !== undefined) { console.log(`${n!}`); }
    if (b !== undefined) { console.log(`${b!}`); }
    if (s !== undefined) { console.log(`'${s!}'`); }
}
function mixed(value: number | string | boolean | undefined): void {
    if (typeof value === 'string') { console.log(`'${value!}'`); }
    if (typeof value === 'boolean') { console.log(`${value!}`); }
}
run(0, false, '');
mixed('');
mixed(false);

let calls = 0;
function array(): number[] | undefined { calls += 1; return [0]; }
function map(): Map<string, string> | undefined { calls += 1; return new Map<string, string>([['key', '']]); }
function closure(): (() => boolean) | undefined { calls += 1; return (): boolean => false; }
function object(): { readonly name: string } | undefined { calls += 1; return { name: `object${calls}` }; }
try {
    console.log(`${array()![0]!} ${calls}`);
    console.log(`'${map()!.get('key')!}' ${calls}`);
    console.log(`${closure()!()} ${calls}`);
    console.log(`${object()!.name} ${calls}`);
} catch { console.log('caught'); } finally { console.log(`finally ${calls}`); }

function tuple(value: readonly [number | undefined, string | undefined]): void {
    console.log(`${value[0]!} '${value[1]!}'`);
}
tuple([0, '']);
function match(value: RegExpMatchArray | null): void {
    if (value !== null) { console.log((value)![0]!); }
}
match('a'.match(/a/));

function run(value: number | string | undefined): void {
    if (typeof value === 'number') { console.log(`${value! + 1}`); }
    if (typeof value === 'string') { console.log(value! + 'ok'); }
}
run(0);
run('');
function present(value: number | string): void {
    if (typeof value === 'number') { console.log(`${value! + 2}`); }
    if (typeof value === 'string') { console.log(value! + 'present'); }
}
present(0);
present('');

